edits.new:
streamFileInput = new FileInputStream("c:\\file.txt");
int bytesRead = streamFileInput.read(byteArray);
if (bytesRead < 0)
{
    IO.writeLine("No data read from file");
}
else
{
    IO.writeLine(new String(byteArray, 0, bytesRead, "UTF-8"));
}
